/// <summary>
/// getMenu's request: the company and the signed-in worker.
/// </summary>
[DataContractAttribute]
class HSMobileOpsMenuRequest
{
    str      dataAreaId;
    str      userName;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public str parmDataAreaId(str _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('UserName')]
public str parmUserName(str _value = userName)
{
    userName = _value;
    return userName;
}
